// Controlled demo-data initialization (opt-in): copies the committed synthetic seed (test/data, generated by
// tools/m04/build-seed.mjs) into the HANA deployer content of a production build. Used only by the MTA
// extension mta-demo.mtaext; a normal production build ships no demo data (see test/seed-data.test.js).
import { cpSync, readdirSync, mkdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';
const root = join(import.meta.dirname, '..', '..');
const target = join(root, 'gen', 'db', 'src', 'csv');
if (!existsSync(join(root, 'gen', 'db'))) { console.error('Run "cds build --production" first.'); process.exit(1); }
mkdirSync(target, { recursive: true });
const files = readdirSync(join(root, 'test', 'data')).filter(f => f.endsWith('.csv'));
for (const f of files) cpSync(join(root, 'test', 'data', f), join(target, f));
console.log(`staged ${files.length} synthetic seed files (SEED-M04-01 + DS-SCENARIOS-01) into ${target}`);
